validate(value) {
  const v = value as Partial<User> | null;
  const issues: StandardSchemaIssue[] = [];
  when(differs(typeof get(v, "id"), 'string'), () => issues = pushedList(issues, [{
    message: 'expected string',
    path: ['id']
  }])));
  when(differs(typeof get(v, "name"), 'string'), () => issues = pushedList(issues, [{
    message: 'expected string',
    path: [{
      key: 'name'
    }]
  }])));
  return when(lengthOf(issues), () => ({
    issues
  }), () => ({
    value: v as User
  }));
}

function defineService<Props extends Forbid<Props, DomainUnitAny>, Return, Schema extends ResponseSchema>(name: string, fn: (props: Props) => Return, options?: ServiceOptions<Schema>): ServiceUnit<(props: Props) => unknown> {
  return when(not(get(options, "schema")), () => tagUnit(name, fn, 'service'), () => {
    const {
      schema
    } = options;
    const checked = (props: Props) => checkServiceReturn(schema, fn(props));
    const unit = tagUnit<typeof checked, ServiceUnit<typeof checked>>(name, checked, 'service');
    return merged(unit, { schema });
  });
}

function normalizeIssues(issues: ReadonlyArray<StandardSchemaIssue>): SchemaIssue[] {
  return mapEach(issues, issue => ({
    message: textFrom(issue.message),
    path: mapEach(orElse(issue.path, () => []), segment => when(and(equals(typeof segment, 'object'), () => differs(segment, null)), () => segment.key, () => segment))
  }));
}

function isThenable(value: unknown): value is PromiseLike<unknown> {
  return and(
    and(equals(typeof value, 'object'), () => differs(value, null)),
    () => equals(typeof (value as { then?: unknown }).then, 'function')
  );
}

function checkResponse<S extends ResponseSchema>(schema: S, value: unknown): ServiceResult<SchemaOutput<S>> | Promise<ServiceResult<SchemaOutput<S>>> {
  type Out = SchemaOutput<S>;
  const toResult = (r: StandardSchemaResult<unknown>): ServiceResult<Out> => when(r.issues, () => schemaError(normalizeIssues(r.issues)), () => ({
    status: 'ok',
    value: r.value as Out
  }));
  return attempt(() => when('~standard' in schema, () => {
    const raw = schema['~standard'].validate(value);
    return when(isThenable(raw), () => thenPromise(resolvePromise(raw), toResult, (e: unknown) => schemaError([{
      message: `schema threw: ${describe(e)}`,
      path: []
    }])), () => toResult(raw));
  }, () => {
    const parsed = schema.safeParse(value);
    return when(parsed.success, () => ({
      status: 'ok',
      value: parsed.data as Out
    }), () => schemaError(normalizeIssues(parsed.error.issues)));
  }), e => schemaError([{
    message: `schema threw: ${describe(e)}`,
    path: []
  }]));
}

send(state, event) {
  return match(event.type, {
    FETCH: () => when(equals(state.status, 'success'), () => ({
      ...state,
      fetching: true,
      request: plus(state.request, 1)
    }), () => ({
      ...state,
      status: 'pending',
      error: null,
      fetching: true,
      request: plus(state.request, 1)
    })),
    RESOLVE: () => when(not(isCurrent(state, event.request)), () => state, () => ({
      ...state,
      status: 'success',
      data: event.data,
      error: null,
      fetching: false,
      updatedAt: orElse(event.at, () => null)
    })),
    REJECT: () => when(not(isCurrent(state, event.request)), () => state, () => ({
      ...state,
      status: 'error',
      error: event.error,
      fetching: false
    })),
    RESET: () => machine.init()
  }, () => state);
}

function csvCell(value: unknown, options: CsvOptions = {}): string {
  const separator = orElse(options.separator, () => ',');
  let text = '';
  choose([[isA(value, Date), () => text = dateAsIsoText(value)], [() => and(differs(value, null), () => differs(value, undefined)), () => text = textFrom(value)]]);
  when(and(orElse(options.safe, () => true), () => doesPatternMatch(FORMULA_START, text)), () => text = `'${text}`);
  return when(or(or(or(hasText(text, separator), () => hasText(text, '"')), () => hasText(text, '\n')), () => hasText(text, '\r')), () => `"${replaceText(text, /"/g, '""')}"`, () => text);
}

function cellOf<T>(row: T, column: Column<T>): unknown {
  return when(equals(typeof column.accessor, 'function'), () => column.accessor(row), () => row[column.accessor]);
}

function toCsv<T>(rows: T[], columns: Column<T>[], options: CsvOptions = {}): string {
  const separator = orElse(options.separator, () => ',');
  const eol = orElse(options.eol, () => '\r\n');
  const lines = [joinWith(mapEach(columns, c => csvCell(c.header, options)), separator)];
  each(rows, row => {
    lines.push(joinWith(mapEach(columns, c => csvCell(cellOf(row, c), options)), separator));
  });
  return join(joinWith(lines, eol), eol);
}

function daysIn(r: RangeState): number {
  return when(differs(r.status, 'complete'), () => 0, () => round(dividedBy(minus(plus(timeOfDate(r.end as Date), 1), timeOfDate(r.start as Date)), DAY)));
}

function applyView<T extends Record<string, unknown>>(rows: T[], v: View, searchFields: (keyof T)[] = []): T[] {
  const active = keepWhere(entriesOf(v.filters), ([, value]) => not(isNoFilter(value)));
  const kept = keepWhere(rows, row => and(isEveryWhere(active, ([id, value]) => equals(row[id], value)), () => matchesSearch(row, v.search, searchFields)));
  return when(equals(v.sort, null), () => kept, () => {
    const {
      id,
      desc
    } = v.sort;
    const indexed = mapEach(kept, (row, i) => ({
      row,
      i
    }));
    const sorted = sortedBy(indexed, (x, y) => {
      const c = compareValues(x.row[id], y.row[id]);
      return when(equals(c, 0), () => minus(x.i, y.i), () => when(and(and(desc, () => not(isEmptyValue(x.row[id]))), () => not(isEmptyValue(y.row[id]))), () => negate(c), () => c));
    });
    return mapEach(sorted, x => x.row);
  });
}

send(state, event) {
  return match(event.type, {
    SET_FILTER: () => when(equals(state.filters[event.id], event.value), () => state, () => view(withKey(state.filters, event.id, event.value), state.search, state.sort)),
    CLEAR_FILTER: () => when(not(event.id in state.filters), () => state, () => {
      const filters = withoutEntry(state.filters, event.id);
      return view(filters, state.search, state.sort);
    }),
    SET_SEARCH: () => when(equals(event.text, state.search), () => state, () => view(state.filters, event.text, state.sort)),
    SORT_BY: () => view(state.filters, state.search, {
      id: event.id,
      desc: orElse(event.desc, () => false)
    }),
    TOGGLE_SORT: () => when(or(equals(state.sort, null), () => differs(state.sort.id, event.id)), () => view(state.filters, state.search, {
      id: event.id,
      desc: false
    }), () => when(not(state.sort.desc), () => view(state.filters, state.search, {
      id: event.id,
      desc: true
    }), () => view(state.filters, state.search, null))),
    RESET: () => machine.init()
  }, () => state);
}

function toXStateConfig<D>(id: string, steps: Step<D>[], data: D, assign: (fn: (args: {
  context: {
    data: D;
  };
  event: any;
}) => {
  data: D;
}) => unknown): Record<string, unknown> {
  const merged = ({
    context,
    event
  }: {
    context: {
      data: D;
    };
    event: any;
  }) => ({
    data: mergedAtom(context.data, orElse(event.data, () => ({})))
  });
  const states: Record<string, unknown> = {};
  each(steps, (step, i) => {
    let target = 'done';
    when(lessThan(i, minus(lengthOf(steps), 1)), () => target = steps[plus(i, 1)].id);
    const on: Record<string, unknown> = {
      NEXT: [{
        target,
        guard: (args: {
          context: {
            data: D;
          };
          event: any;
        }) => canLeave(step, merged(args).data),
        actions: assign(merged)
      }, {
        actions: assign(merged)
      }]
    };
    when(greaterThan(i, 0), () => on.BACK = {
      target: steps[minus(i, 1)].id
    });
    states[step.id] = {
      on
    };
  });
  states.done = {
    type: 'final'
  };
  return {
    id,
    initial: firstOf(steps).id,
    context: {
      data
    },
    states
  };
}

function covers(held: string, required: string): boolean {
  return when(
    or(
      equals(held, '*'),
      () => equals(held, required)
    ),
    () => true,
    () => when(
      doesEndWith(held, ':*'),
      () => doesStartWith(required, sliceText(held, 0, -1)),
      () => false
    )
  );
}

function fieldErrors(issues: Issue[]): Record<string, string> {
  const out: Record<string, string> = {};
  each(issues, issue => {
    const key = joinWith(mapEach(issue.path, String), '.');
    when(not(key in out), () => out[key] = issue.message);
  });
  return out;
}

function onKeyDown(e: KeyboardEvent<HTMLInputElement>) {
  when(
    equals(e.key, 'ArrowDown'),
    () => {
      e.preventDefault();
      when(
        not(open),
        () => {
          setOpen(true);
          setActive(0);
        },
        () => {
          setActive(i => smallestOf([plus(i, 1), minus(lengthOf(matches), 1)]));
        }
      );
    },
    choose(
      [
        [
          equals(e.key, 'ArrowUp'),
          () => {
            e.preventDefault();
            setActive(i => largestOf([minus(i, 1), 0]));
          }
        ],
        [
          and(
            and(equals(e.key, 'Enter'), () => open),
            () => matches[active]
          ),
          () => {
            e.preventDefault();
            choose(matches[active]);
          }
        ],
        [
          and(equals(e.key, 'Escape'), () => open),
          () => {
            e.preventDefault();
            setOpen(false);
          }
        ]
      ]
    )
  );
}

function add(picked: File[]) {
  when(
    and(
      and(
        not(disabled),
        () => not(readOnly)
      ),
      () => lengthOf(picked)
    ),
    () => update(
      when(
        multiple,
        () => concatenated(list, picked),
        () => part(picked, 0, 1)
      )
    )
  );
}

function pageItems(page: number, pageCount: number, siblings = 1): (number | 'gap')[] {
  const wanted = setOf([1, pageCount]);
  repeatWhile(
    () => atMost(minus(page, siblings), pageCount),
    () => addToWeakSet(wanted, minus(page, siblings)),
    () => plus(page, siblings)
  );
  const sorted = sortedBy([...wanted], (a, b) => minus(a, b));
  const out: (number | 'gap')[] = [];
  each(sorted, (p, i) => {
    when(
      and(greaterThan(i, 0), () => greaterThan(minus(p, sorted[minus(i, 1)]), 1)),
      () => out.push('gap'),
      () => {}
    );
    out.push(p);
  });
  return out;
}
